function renderProjects(){
 document.querySelector('#projects').innerHTML=projects.map((p,i)=>`<article class="project-card reveal ${p.screens?'has-screens':''}"><button class="project-open" data-project="${i}" aria-label="${language==='ar'?'عرض تفاصيل':'View details for'} ${p.name}" aria-haspopup="dialog">${renderProjectCover(p,i)}<div class="project-info"><div><h3 dir="ltr">${p.name}</h3><p>${localized(p.subtitle)}</p></div><span class="project-arrow" aria-hidden="true">↗</span></div></button><div class="project-tags">${p.tags.map(tag=>`<span>${tag}</span>`).join('')}</div></article>`).join('');
 observeReveals();
}
function renderProjectCover(p,i){
 if(p.presentation)return `<div class="project-art ava-cover ${p.presentation}-presentation"><div class="ava-cover-heading"><strong dir="ltr">${p.name}<span>.</span></strong><span class="presentation-label">${t('mobile')}</span></div><div class="ava-cover-image"><img src="${p.screens[0].src}" width="1536" height="1024" loading="lazy" decoding="async" alt=""></div><span class="ava-invitation">${language==='ar'?'استعرض الواجهات':'Explore the interfaces'} ↗</span></div>`;
 if(p.flowBoards)return `<div class="project-art alopr-cover"><div class="alopr-cover-heading"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${t('mobile')}</span><strong dir="ltr">Alopr<span>.</span></strong></div><span class="alopr-invitation">${language==='ar'?'استعرض ٦ مجموعات':'Explore 6 flows'} ↗</span></div><div class="alopr-cover-screen" aria-hidden="true"><img src="assets/alopr/doctor-flow.webp" width="1445" height="1031" loading="lazy" decoding="async" alt=""></div></div>`;
 if(p.screens&&p.desktop)return `<div class="project-art quarto-cover"><div class="quarto-cover-heading"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${t('desktop')}</span><strong dir="ltr">Quarto<span>.</span></strong></div><span class="quarto-invitation">${language==='ar'?'استعرض ٩ صور':'Explore 9 screens'} ↗</span></div><div class="quarto-cover-screen" aria-hidden="true"><img src="assets/quarto/gaming-stations.webp" width="1800" height="1250" loading="lazy" decoding="async" alt=""></div></div>`;
 if(p.screens)return `<div class="project-art medcare-cover"><div class="medcare-cover-copy"><span class="eyebrow">07 / ${t('mobile')}</span><strong class="medcare-wordmark" dir="ltr">Medcare<span>+</span></strong><h3>${t('careAtHome')}</h3><p>${t('medcareCover')}</p><span class="gallery-invitation">${t('viewScreens')} <span aria-hidden="true">↗</span></span></div><div class="medcare-cover-screens" aria-hidden="true"><div class="screen-frame cover-side"><img src="assets/medcare/lab-tests.png" alt="" width="402" height="874" loading="lazy"></div><div class="screen-frame cover-main"><img src="assets/medcare/home.png" alt="" width="402" height="1250" loading="lazy"></div><div class="screen-frame cover-side"><img src="assets/medcare/staff-requests.png" alt="" width="402" height="1250" loading="lazy"></div></div></div>`;
 return `<div class="project-art" style="--project-bg:${p.bg};--project-fg:${p.fg}"><div class="art-grid" aria-hidden="true"></div><div class="art-top"><span>${String(i+1).padStart(2,'0')} / ${t(p.desktop?'desktop':'mobile')}</span><span aria-hidden="true">↗</span></div><div class="art-name" dir="ltr">${p.name}<span style="font-weight:400;opacity:.5">.</span></div><div class="art-bottom"><span>${localized(p.category)}</span><span class="art-mark" aria-hidden="true">${p.mark}</span></div></div>`;
}
